    "text": " instance_policy is subordinate to this exact construction revision: one saved instance ID per entry, version=1, with role/quantity_policy/reason. Allowed pairs: build_part/manufacture, existing_part/retain, prefabricated_part/complete_item, reference/exclude, unknown/unknown. Classify from evidence or an explicit design decision; never guess from a name. null preserves uncertainty and inherits only previously classified stable IDs. After saving a changed revision, read_construction_changes and complete the affected outputs before claiming delivery."
  },
  {
    "name": "read_construction_draft",
    "text": " Read instance_policy for this exact revision. Missing historical policy means unknown; classify existing IDs with change_construction_roles before deriving manufacturing quantities."
  },
  {
    "name": "check_construction_draft",
    "text": " Reference geometry remains visible but is excluded from physical-contact checks. Do not join a reference instance to a physical member. Reference clearances and motion remain unverified. A concept geometry check does not invent quantities for unknown roles."
  },
  {
    "name": "derive_construction_lists",
    "text": " Lists use construction-blanks-role-v1 and include only manufacture instances in BOM/cuts. Existing parts, complete prefabricated items and references are reported separately. Availability, procurement and suitability remain explicit gaps. Unknown roles block quantity lists."
  },
  {
    "name": "derive_cad_material_requirement",
    "text": " Construction blank role v2 counts only manufacture instances at the exact construction revision. Historical drawing-only or unclassified geometry must be transitioned/classified first; do not guess roles or duplicate an existing need."
  },
  {
    "name": "check_construction_cut_fit",
    "text": " Sheet placement covers only the manufacture instances at this exact revision. Preserve visible instance ordinals/labels. Existing, prefabricated and reference instances are not new cut blanks. Unknown roles block quantities."
  },
  {
    "name": "save_construction_cut_plan",
    "text": " Save coverage only for exact current manufacturing piece needs. After a construction change, use read_construction_changes/continue_construction_change to reuse the same output identity and stored cutting inputs. Purchases and reservations require their normal explicit resolution."
  },
  {
    "name": "change_construction_parameters",
    "text": " After the saved exact parameter revision, read_construction_changes. Code retains stable instance roles and records the linked drawings, requirements, cuts and work reviews; a construction receipt alone does not prove their completion."
  },
  {
    "name": "transition_legacy_drawing",
    "text": " Historical instance roles remain unknown. Read the prepared checkpoint and explicitly classify its saved instance IDs before deriving manufacturing needs; the transition does not infer roles or backfill history."
  },
  {
    "name": "read_cad_artifact",
    "text": " instance_policy is the exact drawn construction policy, never its later head. After changes, read_construction_changes for persisted pending work and exact output identities."
  },
  {
    "name": "design_project_cad",
    "text": " A changed construction records affected drawing work. Use continue_construction_change to read the original drawing/step and exact construction pins, then render with those pins. All reference geometry/bounds and kernel diagnostics remain visible. Reference overlaps are contextual; physical overlaps still stop publication and reference clearances remain unverified. Successful typed publication completes that same saved consequence. Pending/failed rendering remains pending; it cannot prove delivery."
  }
]$consequence_contracts$::jsonb;
 policies jsonb:=$consequence_policies$[{"name":"change_construction_roles","description":"Classify saved part-instance roles without reconstructing geometry.","how_to":"Use exact IDs and role/quantity pairs from the saved construction; unknown stays unknown. Then read the saved affected-output work.","schema_version":1,"always_load":false,"preload_phases":[],"active":true},{"name":"continue_construction_change","description":"Recalculate one saved affected output from canonical inputs.","how_to":"Send an item ID and exact construction version. Needs precede cutting. Preserve purchases/reservations and performed work; record a work review separately from recomputation.","schema_version":1,"always_load":false,"preload_phases":[],"active":true},{"name":"read_construction_changes","description":"Read saved affected-output work for an exact construction revision.","how_to":"Follow every page; use stable output identities and recorded completion receipts. Superseded work cannot continue against a new construction head.","schema_version":1,"always_load":false,"preload_phases":[],"active":true}]$consequence_policies$::jsonb;
 patch jsonb; policy jsonb; contract jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}'; tool_name text;
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if exists(select 1 from shared.ai_prompts where app='bob' and prompt_key='tools.read_construction_changes') then raise exception 'construction_consequences_already_published'; end if;
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_construction_draft';
 if not found then raise exception 'construction_consequences_template_missing'; end if;
 for patch in select value from jsonb_array_elements(patches) loop
  contract:=patch->'contract';tool_name:=coalesce(contract->>'name',patch->>'name');
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.'||tool_name and p.definition_kind='tool_contract';
  if not found then
   select value into policy from jsonb_array_elements(policies) where value->>'name'=tool_name;
   if policy is null then raise exception 'construction_consequences_contract_missing'; end if;
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind) values('bob','tools.'||tool_name,policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
   prior:=template;definition:=prior.definition||contract||jsonb_build_object('handler',tool_name,'required_parameters',contract#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',patch->>'text');
  else
   prompt_uuid:=prior.prompt_id;definition:=prior.definition;
   if contract is not null then definition:=definition||contract||jsonb_build_object('required_parameters',contract#>'{parameters,required}','optional_parameters','[]'::jsonb); end if;
   definition:=definition||jsonb_build_object('additional_description',coalesce(prior.definition->>'additional_description','')||(patch->>'text'));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,'tool_contract',1,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','construction-instance-roles-and-consequences'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('tools.'||tool_name,version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' and p.definition_kind='tool_contract' for update of p;
 if not found then raise exception 'construction_consequences_toolbox_missing'; end if;
 definition:=prior.definition;
 for policy in select value from jsonb_array_elements(policies) loop
  insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
   values(policy->>'name',policy->>'description',policy->>'how_to',(policy->>'schema_version')::integer,(policy->>'always_load')::boolean,array(select jsonb_array_elements_text(policy->'preload_phases')),(policy->>'active')::boolean);
  definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
  definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.'||(policy->>'name')));
  definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Drawings and CAD' then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array(policy->>'name')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 end loop;
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','construction-instance-roles-and-consequences'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $construction_consequences_catalog$;
commit;
